// Pega todos os leads da planilha
const items = $input.all();

// Configuração
const LIMIT_PER_ACCOUNT = 500;  // Limite do Gmail
const TOTAL_ACCOUNTS = 6;        // Suas 6 contas

// Calcula capacidade total diária
const capacidadeTotal = TOTAL_ACCOUNTS * LIMIT_PER_ACCOUNT; // 3.000 emails

// VERIFICAÇÃO DE SEGURANÇA
if (items.length > capacidadeTotal) {
  throw new Error(`⚠️ ATENÇÃO: Você tem ${items.length} leads, mas só pode enviar ${capacidadeTotal} emails por dia (6 contas × 500 emails)`);
}

console.log(`📊 Total de leads: ${items.length}`);
console.log(`📧 Emails por conta: ~${Math.ceil(items.length / TOTAL_ACCOUNTS)}`);

// Distribui cada lead para uma conta
const itemsComConta = items.map((item, index) => {

  // MÁGICA: usa módulo (%) para rotacionar
  const accountId = (index % TOTAL_ACCOUNTS) + 1;

  // Log para acompanhar distribuição
  if (index < 10 || index % 100 === 0) {
    console.log(`Lead ${index + 1} → Conta ${accountId}`);
  }

  return {
    json: {
      // Mantém todos os dados originais do lead
      ...item.json,

      // Adiciona informações da conta
      selected_account_id: accountId,
      lead_position: index + 1,
      total_leads: items.length,
      account_info: `Conta ${accountId} de ${TOTAL_ACCOUNTS}`
    }
  };
});

// Contagem final por conta
const countPerAccount = {};
for (let i = 1; i <= TOTAL_ACCOUNTS; i++) {
  countPerAccount[`Conta ${i}`] = itemsComConta.filter(item => item.json.selected_account_id === i).length;
}

console.log('\n📊 DISTRIBUIÇÃO FINAL:');
console.log(JSON.stringify(countPerAccount, null, 2));

return itemsComConta;

